VX_FROM = {"liberty": 12500, "comfort": 22300, "physio": 35700, "xr": 41700}

def _p(n, sep):
    return f"{n:,}".replace(",", sep)

def vx_prices(lang):
    sep = {"sr": ".", "hu": " ", "en": ",", "ru": " "}[lang]
    return {k: dict(one=_p(v, sep), pair=_p(v * 2, sep), one_num=v) for k, v in VX_FROM.items()}

